def esc(value) -> str:
    return html.escape(str(value), quote=True)


def frame(title: str, current: str, content: str, description: str) -> str:
    nav = "".join(
        f'<a href="{href}" class="{"active" if key == current else ""}" '
        f'{"aria-current=page" if key == current else ""}>{label}</a>'
        for href, label, key in NAV
    )
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light dark"><meta name="description" content="{esc(description)}">
<title>{esc(title)} · Drone audio model record</title><link rel="stylesheet" href="assets/report.css">
<script>document.documentElement.classList.add('js-motion');</script><script src="assets/report-data.js"></script>
<script src="assets/report.js" defer></script></head><body data-page="{current}">
<header class="masthead"><a class="wordmark" href="index.html" aria-label="Model report overview"><svg viewBox="0 0 34 34" aria-hidden="true"><path d="M3 18h5l3-9 5 17 4-12 3 5h8"/><circle cx="29" cy="19" r="2"/></svg><span>Drone audio<br><b>model record</b></span></a>
<nav class="primary-nav" aria-label="Report pages">{nav}</nav><div class="head-actions"><span class="offline-mark"><i></i> Offline report</span><button class="theme-button" id="theme-toggle" type="button" aria-label="Switch colour theme">◐</button></div></header>
<main id="main">{content}</main><footer class="site-footer"><span>Frozen comparison · drone audio classification</span><span>Generated from saved results · no refit or new inference</span><a href="index.html">Back to overview ↑</a></footer>
</body></html>'''


def mini_bars(model: dict) -> str:
    variants = model["variants"]
    if not variants:
        return '<p class="quiet">No variant ledger for this baseline.</p>'
    lo = min(float(x["validation_f1"]) for x in variants)
    hi = max(float(x["validation_f1"]) for x in variants)
    spread = max(hi - lo, 0.01)
    bars = []
    for item in variants:
        score = float(item["validation_f1"])
        height = 18 + 78 * (score - lo) / spread
        bars.append(f'<i class="variant-bar {"best" if score == hi else ""}" style="--bar:{height:.1f}%" '
                    f'title="{esc(item.get("name", item.get("id", "candidate")))} · validation F1 {score:.4f}"></i>')
    return f'<div class="variant-strip" role="img" aria-label="{len(variants)} recorded validation variants">{"".join(bars)}</div>'


def model_cards(data: dict) -> str:
    by_id = {m["id"]: m for m in data["models"]}
    result = []
    for family in data["cards"]:
        entries = []
        for mid in family["models"]:
            m = by_id[mid]
            details = "".join(
                f'<tr><td>{esc(v.get("name", v.get("id", "recorded setting")))}</td>'
                f'<td>{float(v["validation_f1"]):.4f}</td><td>{int(v.get("seeds", 1))}</td></tr>'
                for v in sorted(m["variants"], key=lambda x: float(x["validation_f1"]), reverse=True)
            )
            entries.append(f'''<article class="model-entry" data-model="{esc(m['id'])}" data-family="{esc(m['family'])}">
<div class="model-entry-head"><div><h3>{esc(m['name'])}</h3><p>{esc(m['family'])} · seed {m['seed']} · threshold <code>{m['threshold']:.6g}</code></p></div>
<div class="model-score"><b>{m['test_f1']:.4f}</b><span>test F1</span></div></div>
<p class="model-description">{esc(m['description'])}</p>
<p class="search-scope"><span class="micro-label">Recorded search</span> {esc(m.get('search', 'See variant ledger'))}</p>
<div class="variant-row"><div><span class="micro-label">Validation variants</span>{mini_bars(m)}</div>
<div class="metrics-inline"><span>Validation <b>{m['validation_f1']:.4f}</b></span><span>95% group CI <b>{m['f1_low']:.3f}–{m['f1_high']:.3f}</b></span><span>AUC <b>{m['auc']:.4f}</b></span></div></div>
<details class="variant-details"><summary>Open all {len(m['variants'])} recorded variant scores</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>Setting</th><th>Validation F1</th><th>Seeds</th></tr></thead><tbody>{details}</tbody></table></div></details></article>''')
        result.append(f'<section class="family-section" data-family="{esc(family["title"])}"><div class="family-label"><h2>{esc(family["title"])}</h2><span>{len(family["models"])} final {"fit" if len(family["models"]) == 1 else "fits"}</span></div>{"".join(entries)}</section>')
    return "".join(result)


def leaderboard(data: dict) -> str:
    rows = []
    for m in sorted(data["models"], key=lambda x: x["test_f1"], reverse=True):
        rows.append(f'''<tr data-model="{esc(m['id'])}"><th scope="row"><span class="rank">{len(rows)+1:02d}</span>{esc(m['name'])}<small>{esc(m['family'])}</small></th>
<td class="num validation-cell">{m['validation_f1']:.4f}</td><td class="num test-cell"><b>{m['test_f1']:.4f}</b><small>{m['f1_low']:.3f}–{m['f1_high']:.3f}</small></td>
<td class="num">{m['auc']:.4f}</td><td class="num">{m['precision']:.3f}</td><td class="num">{m['recall']:.3f}</td><td class="num">{m['far']:.3f}</td></tr>''')
    return "".join(rows)


def stage_chart(data: dict) -> str:
    s = data["stages"]
    variants = [{"name": "A0 default", "mean": s["baseline_f1"], "accepted": False}, *s["variants"]]
    result = []
    for v in variants:
        result.append(f'''<div class="stage-bar-row"><span>{esc(v['name'])}</span><div class="stage-track"><i class="acceptance-line" style="--threshold:{s['threshold']*100:.3f}%"></i>
<i class="stage-fill {"accepted" if v['accepted'] else ""}" style="--value:{v['mean']*100:.3f}%"></i></div><b>{v['mean']:.4f}</b></div>''')
    return "".join(result)


def cnn_stage_buttons(data: dict) -> str:
    labels = [
        ("A", "Frontend baseline", data["stages"]["history"]["A"]),
        ("B1", "Filtered conditions", data["stages"]["history"]["B1"]),
        ("B2", "Input variants", data["stages"]["history"]["B2"]),
        ("B3", "Augmentation", data["stages"]["history"]["B3"]),
        ("C", "Architecture search", data["stages"]["history"]["C"]),
        ("D", "Final seed run", data["stages"]["history"]["D"]),
    ]
    return "".join(f'<button type="button" class="stage-tab {"selected" if i == 0 else ""}" data-stage="{i}" aria-pressed="{str(i==0).lower()}"><b>{tag}</b><span>{esc(title)}</span></button>' for i, (tag, title, _) in enumerate(labels))


def stage_copy_json(data: dict) -> str:
    labels = [
        data["stages"]["history"]["A"], data["stages"]["history"]["B1"],
        data["stages"]["history"]["B2"], data["stages"]["history"]["B3"],
        data["stages"]["history"]["C"], data["stages"]["history"]["D"],
    ]
    return json.dumps(labels, ensure_ascii=False).replace("</", "<\\/")


def table_rows(rows: list[dict], columns: list[tuple[str, str, str]]) -> str:
    out = []
    for row in rows:
        cells = []
        for key, label, kind in columns:
            raw = row.get(key, "")
            value = esc(raw)
            cells.append(f'<td class="{kind}">{value}</td>')
        out.append("<tr>" + "".join(cells) + "</tr>")
    return "".join(out)


def render_pages(data: dict) -> dict[str, str]:
    top = next(m for m in data["models"] if m["id"] == "30_cnn")
    control = next(m for m in data["models"] if m["id"] == "30_cnn_control")
    scores = data["test"]
    cnn = data["stages"]
    paired_rows = []
    for p in data["paired"]:
        lo = float(p["f1_difference_ci_low"])
        hi = float(p["f1_difference_ci_high"])
        paired_rows.append({
            "comparison": p["comparison"].replace("__minus__", " − ").replace("_", " "),
            "low": lo, "high": hi, "excludes": (lo > 0 or hi < 0),
        })
    max_pair = max(max(abs(p["low"]), abs(p["high"])) for p in paired_rows)
    for p in paired_rows:
        p["left"] = 50 + 50 * p["low"] / max_pair
        p["width"] = 50 * (p["high"] - p["low"]) / max_pair
        p["mid"] = 50 + 50 * (p["low"] + p["high"]) / (2 * max_pair)
    paired_html = "".join(f'''<div class="paired-line"><span>{esc(p['comparison'])}</span><div class="forest-track"><i class="forest-zero"></i><i class="forest-range {"significant" if p['excludes'] else ""}" style="--left:{p['left']:.2f}%;--width:{p['width']:.2f}%"></i><i class="forest-dot {"significant" if p['excludes'] else ""}" style="--mid:{p['mid']:.2f}%"></i></div><code>[{p['low']:+.3f}, {p['high']:+.3f}]</code></div>''' for p in paired_rows)

    op_rows = []
    selected_op_models = {"30_cnn", "30_cnn_control", "18_svm_rbf", "20_mlp", "15_random_forest"}
    short_names = {m["id"]: m["name"] for m in data["models"]}
